command:
if (actor.system.derived.resolve.value == 0) {
  ui.notifications.warn("Monster Girl does not have enough resolve to transform");
  return;
}

const values = {
  true: {
    "system.attributes.fighting.value": 3,
    "system.attributes.agility.value": 3,
    "system.attributes.strength.value": 2
  },
  false: {
    "system.attributes.fighting.value": 7,
    "system.attributes.agility.value": 5,
    "system.attributes.strength.value": 8
  }
};

const isTransformed = actor.system.attributes.strength.value == 8;
const valuesToUpdate = values[isTransformed];
let transformForm = "Amanda";
let protectionDisabled = true;

if (isTransformed) {
  valuesToUpdate["system.derived.health.value"] = Math.min(actor.system.derived.health.value - 6, 6);
}
else {
  transformForm = "Monster Girl";
  protectionDisabled = false;
  valuesToUpdate["system.derived.health.value"] = Math.min(actor.system.derived.health.value + 6, 12);
}

valuesToUpdate["system.derived.resolve.value"] = actor.system.derived.resolve.value - 1;

await actor.update(valuesToUpdate);
const protectionActiveEffect = await fromUuid("Actor.P1X6rWlnWQzuuTI1.Item.lLqOnZFBVY5m5Kwu.ActiveEffect.jblmT9Mxb7Ah3Snk");
await protectionActiveEffect.update({ "disabled": protectionDisabled });
ui.notifications.info(`Transforming to ${transformForm}.`);
